SELECT x.n, x.body,
  json_patch(json_patch('{}', json_object('path', x.path, 'epoch', x.epoch, 'outcome', x.outcome, 'key', x.key, 'fresh', x.fresh, 'reused', x.reused, 'fresh_from', x.fresh_from, 'again', CASE WHEN coalesce(x.again_fresh, x.again_reused) IS NOT NULL THEN json_object('fresh', x.again_fresh, 'reused', x.again_reused) END, 'fields', CASE WHEN coalesce(x.base, x.bin, x.checker, x.closure, x.config, x.corpus, x.entry, x.env, x.identity, x.field_key, x.node, x.remote, x.repo, x.rust_identity, x.selection, x.sha, x.step, x.tools, x.tree) IS NOT NULL THEN json_object('base', x.base, 'bin', x.bin, 'checker', x.checker, 'closure', x.closure, 'config', x.config, 'corpus', x.corpus, 'entry', x.entry, 'env', x.env, 'identity', x.identity, 'key', x.field_key, 'node', x.node, 'remote', x.remote, 'repo', x.repo, 'rust_identity', x.rust_identity, 'selection', x.selection, 'sha', x.sha, 'step', x.step, 'tools', x.tools, 'tree', x.tree) END, 'repeated', CASE x.repeated WHEN 1 THEN json('true') WHEN 0 THEN json('false') END)), coalesce(x.rest, '{}')) AS doc
FROM reuse_shadow x
